import React, { useState, useEffect } from "react";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";

const App = () => {
  const [activePage, setActivePage] = useState("chat");
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [topics, setTopics] = useState([]);
  const [darkMode, setDarkMode] = useState(() => {
    return localStorage.getItem("darkMode") === "true"; // Load from storage
  });

  // Load messages & topics from localStorage on app start
  useEffect(() => {
    const savedMessages = JSON.parse(localStorage.getItem("messages")) || [];
    const savedTopics = JSON.parse(localStorage.getItem("topics")) || [];
    setMessages(savedMessages);
    setTopics(savedTopics);
    setIsLoading(false);
  }, []);

  // Save messages & topics when updated
  useEffect(() => {
    if (!isLoading && messages.length > 0) {
      localStorage.setItem("messages", JSON.stringify(messages));
    }
  }, [messages, isLoading]);

  useEffect(() => {
    if (!isLoading && topics.length > 0) {
      localStorage.setItem("topics", JSON.stringify(topics));
    }
  }, [topics, isLoading]);

  // 🔹 Apply dark mode styles dynamically
  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
    } else {
      document.body.classList.remove("dark-mode");
    }
  }, [darkMode]);

  // 🔹 Toggle dark mode
  const toggleDarkMode = () => {
    setDarkMode((prev) => {
      const newMode = !prev;
      localStorage.setItem("darkMode", newMode);
      return newMode;
    });
  };

  return (
    <div className="app-container">
      {/* 🔹 Dark Mode Button - Positioned at the Top-Right */}
      <button className="dark-mode-btn" onClick={toggleDarkMode}>
        {darkMode ? "☀️ Light Mode" : "🌙 Dark Mode"}
      </button>

      {/* Sidebar Navigation */}
      <Navbar activePage={activePage} setActivePage={setActivePage} />

      {/* Main Content Area */}
      <div className="content">
        {activePage === "chat" && (
          <ChatBox 
            messages={messages} 
            setMessages={setMessages} 
            setLatestQuery={setLatestQuery} 
          />
        )}
        {activePage === "youtube" && <YouTube latestQuery={latestQuery} />}
        {activePage === "wikipedia" && <Wikipedia latestQuery={latestQuery} />}
        {activePage === "test" && (
          <Test 
            messages={messages} 
            latestQuery={latestQuery} 
            topics={topics} 
            setTopics={setTopics}  
          />
        )}
      </div>

      {/* Footer */}
      <footer className="footer">
        <p>&copy; 2025 PAT | @Indrajit002</p>
      </footer>
    </div>
  );
};

export default App;
